//! `arachne/SkeletalTrapezoidation.h/.cpp`: the main class of the dynamic beading strategies.
//!
//! The input polygon region is decomposed into trapezoids and represented as a half-edge
//! data-structure. Central edges get bead counts from the beading strategy, transitions are
//! inserted where the bead count changes and finally the toolpaths are generated by connecting
//! the junctions of each quad.

use std::collections::HashSet;

use voronoi::{VoronoiBuilder, VoronoiDiagram};

use super::graph::{EdgeData, EdgeType, Graph, Joint, STEdge, STNode};
use crate::beading_strategy::{Beading, BeadingStrategy};
use crate::geometry::point2ll::{dot, normal, shorter_then, turn90_ccw, v_size, Point2LL};
use crate::geometry::Shape;
use crate::settings::types::AngleRadians;
use crate::utils::coord::Coord;
use crate::utils::extrusion_line::{ExtrusionJunction, ExtrusionLine, LineJunctions, VariableWidthLines};
use crate::utils::index_list::{IndexList, NIL};
use crate::utils::linear_alg_2d;
use crate::utils::polygon_utils::PolygonUtils;
use crate::utils::polygons_point_index::PolygonsSegmentIndex;
use crate::utils::section_type::SectionType;
use crate::utils::voronoi_utils as vu;

/// A limit to how long it'll keep searching for adjacent beads.
const SKELETAL_TRAPEZOIDATION_BEAD_SEARCH_MAX: Coord = 1000;
/// Filter areas marked as 'central' smaller than this.
const CENTRAL_FILTER_DIST: Coord = 20;
/// Generic arithmatic inaccuracy. Only used to determine whether a transition really needs to insert an extra edge.
const SNAP_DIST: Coord = 20;

type Segment = PolygonsSegmentIndex;

/// Representing the location along an edge where the anchor position of a transition should be placed.
#[derive(Clone, Copy, Debug)]
pub struct TransitionMiddle {
    /// Position along edge as measure from edge.from.p
    pub pos: Coord,
    pub lower_bead_count: i32,
    /// The feature radius at which this transition is placed
    pub feature_radius: Coord,
}

/// Represents the location along an edge where the lower or upper end of a transition should be placed.
#[derive(Clone, Copy, Debug)]
pub struct TransitionEnd {
    /// Position along edge as measure from edge.from.p, where the edge is always the half edge oriented from lower to higher R
    pub pos: Coord,
    pub lower_bead_count: i32,
    /// Whether this is the ed of the transition with lower bead count
    pub is_lower_end: bool,
}

/// `SkeletalTrapezoidationJoint::BeadingPropagation`.
#[derive(Clone, Debug)]
pub struct BeadingPropagation {
    pub beading: Beading,
    pub dist_to_bottom_source: Coord,
    pub dist_from_top_source: Coord,
    pub is_upward_propagated_only: bool,
}

impl BeadingPropagation {
    pub fn new(beading: Beading) -> Self {
        BeadingPropagation { beading, dist_to_bottom_source: 0, dist_from_top_source: 0, is_upward_propagated_only: false }
    }
}

/// Auxiliary for referencing one transition along an edge which may contain multiple transitions.
#[derive(Clone, Copy, Debug)]
struct TransitionMidRef {
    edge: usize,
    transition_it: usize,
}

pub struct SkeletalTrapezoidation<'a> {
    /// How pointy a region should be before we apply the method. Equals 180* - limit_bisector_angle
    transitioning_angle: AngleRadians,
    /// approximate size of segments when parabolic VD edges get discretized (and vertex-vertex edges)
    discretization_step_size: Coord,
    /// Filter transition mids (i.e. anchors) closer together than this
    transition_filter_dist: Coord,
    /// The allowed line width deviation induced by filtering
    allowed_filter_deviation: Coord,
    /// When there are different beadings propagated from below and from above, use this transitioning distance
    beading_propagation_transition_dist: Coord,
    #[allow(dead_code)]
    layer_idx: i32,
    #[allow(dead_code)]
    section_type: SectionType,
    beading_strategy: &'a BeadingStrategy,

    pub graph: Graph,

    /// Mapping each voronoi VD edge to the corresponding halfedge HE edge.
    vd_edge_to_he_edge: Vec<usize>,
    vd_node_to_he_node: Vec<usize>,

    // Storage behind the weak pointers of the edge and node data (`ptr_vector_t`s in C++).
    transitions_store: Vec<IndexList<TransitionMiddle>>,
    transition_ends_store: Vec<IndexList<TransitionEnd>>,
    beadings_store: Vec<BeadingPropagation>,
    junctions_store: Vec<LineJunctions>,

    /// (Eventual) returned 'polylines per index' result (from generateToolpaths). Binned by inset_idx.
    generated_toolpaths: Vec<VariableWidthLines>,
}

impl<'a> SkeletalTrapezoidation<'a> {
    #[allow(clippy::too_many_arguments)]
    pub fn new(
        polys: &Shape,
        beading_strategy: &'a BeadingStrategy,
        transitioning_angle: AngleRadians,
        discretization_step_size: Coord,
        transition_filter_dist: Coord,
        allowed_filter_deviation: Coord,
        beading_propagation_transition_dist: Coord,
        layer_idx: i32,
        section_type: SectionType,
    ) -> Self {
        let mut st = SkeletalTrapezoidation {
            transitioning_angle,
            discretization_step_size,
            transition_filter_dist,
            allowed_filter_deviation,
            beading_propagation_transition_dist,
            layer_idx,
            section_type,
            beading_strategy,
            graph: Graph::default(),
            vd_edge_to_he_edge: Vec::new(),
            vd_node_to_he_node: Vec::new(),
            transitions_store: Vec::new(),
            transition_ends_store: Vec::new(),
            beadings_store: Vec::new(),
            junctions_store: Vec::new(),
            generated_toolpaths: Vec::new(),
        };
        st.construct_from_polygons(polys);
        st
    }

    // =====================================================================================
    //    INITIALIZATION
    // =====================================================================================

    /// Get the node which the VD node maps to, or create a new mapping if there wasn't any yet.
    fn make_node(&mut self, vd_node: usize, p: Point2LL) -> usize {
        let he = self.vd_node_to_he_node[vd_node];
        if he == NIL {
            let node = self.graph.nodes.push_front(STNode::new(Joint::default(), p));
            self.vd_node_to_he_node[vd_node] = node;
            node
        } else {
            he
        }
    }

    /// Transfer an edge from the VD to the HE and perform discretization of parabolic edges (and vertex-vertex edges).
    #[allow(clippy::too_many_arguments)]
    fn transfer_edge(
        &mut self,
        vd: &VoronoiDiagram,
        from: Point2LL,
        to: Point2LL,
        vd_edge: usize,
        prev_edge: &mut usize,
        start_source_point: Point2LL,
        end_source_point: Point2LL,
        points: &[Point2LL],
        segments: &[Segment],
    ) {
        let vd_twin = vd.edge(vd_edge).twin();
        let source_twin = self.vd_edge_to_he_edge[vd_twin];
        if source_twin != NIL {
            // Twin segment(s) have already been made
            let end_node = self.vd_node_to_he_node[vd.vertex1(vd_edge)];
            let mut twin = source_twin;
            loop {
                assert!(twin != NIL, "Encountered a voronoi edge without twin.");
                let edge = self.graph.edges.push_front(STEdge::new(EdgeData::new(EdgeType::Normal)));
                let g = &mut self.graph;
                g.edges[edge].from = g.edges[twin].to;
                g.edges[edge].to = g.edges[twin].from;
                g.edges[edge].twin = twin;
                g.edges[twin].twin = edge;
                let ef = g.edges[edge].from;
                g.nodes[ef].incident_edge = edge;

                if *prev_edge != NIL {
                    g.edges[edge].prev = *prev_edge;
                    g.edges[*prev_edge].next = edge;
                }

                *prev_edge = edge;

                if g.edges[edge].to == end_node {
                    return;
                }

                let tp = g.edges[twin].prev;
                if tp == NIL || g.edges[tp].twin == NIL || g.edges[g.edges[tp].twin].prev == NIL {
                    crate::log_error!("Discretized segment behaves oddly!");
                    return;
                }

                g.make_rib(prev_edge, start_source_point, end_source_point);
                let g = &self.graph;
                twin = g.edges[g.edges[g.edges[twin].prev].twin].prev;
            }
        } else {
            let discretized = self.discretize(vd, vd_edge, points, segments);
            if discretized.len() < 2 {
                crate::log_warn!("Discretized Voronoi edge is degenerate.");
            }

            let mut v0 = if *prev_edge != NIL { self.graph.edges[*prev_edge].to } else { self.make_node(vd.edge(vd_edge).vertex0(), from) };
            for p1_idx in 1..discretized.len() {
                let p1 = discretized[p1_idx];
                let v1 = if p1_idx < discretized.len() - 1 {
                    self.graph.nodes.push_front(STNode::new(Joint::default(), p1))
                } else {
                    self.make_node(vd.vertex1(vd_edge), to)
                };

                let g = &mut self.graph;
                let edge = g.edges.push_front(STEdge::new(EdgeData::new(EdgeType::Normal)));
                g.edges[edge].from = v0;
                g.edges[edge].to = v1;
                g.nodes[v0].incident_edge = edge;

                if *prev_edge != NIL {
                    g.edges[edge].prev = *prev_edge;
                    g.edges[*prev_edge].next = edge;
                }

                *prev_edge = edge;
                v0 = v1;

                if p1_idx < discretized.len() - 1 {
                    // Rib for last segment gets introduced outside this function!
                    g.make_rib(prev_edge, start_source_point, end_source_point);
                }
            }
            if self.vd_edge_to_he_edge[vd_edge] == NIL {
                self.vd_edge_to_he_edge[vd_edge] = *prev_edge;
            }
        }
    }

    /// Discretize a Voronoi edge that represents the medial axis of a vertex-line region or
    /// vertex-vertex region into small segments.
    fn discretize(&self, vd: &VoronoiDiagram, vd_edge: usize, points: &[Point2LL], segments: &[Segment]) -> Vec<Point2LL> {
        // Terminology in this function assumes that the edge moves horizontally from left to right.
        let e = vd.edge(vd_edge);
        let left_cell = e.cell();
        let right_cell = vd.edge(e.twin()).cell();
        let start = vu::p(vd, e.vertex0());
        let end = vu::p(vd, vd.vertex1(vd_edge));

        let point_left = vd.cell(left_cell).contains_point();
        let point_right = vd.cell(right_cell).contains_point();
        if (!point_left && !point_right) || e.is_secondary() {
            // Source vert is directly connected to source segment
            vec![start, end]
        } else if point_left != point_right {
            // This is a parabolic edge between a point and a line.
            let p = vu::get_source_point(vd, if point_left { left_cell } else { right_cell }, points, segments);
            let s = vu::get_source_segment(vd, if point_left { right_cell } else { left_cell }, points, segments);
            vu::discretize_parabola(p, s, start, end, self.discretization_step_size, self.transitioning_angle.value())
        } else {
            // This is a straight edge between two points.
            // While the edge is straight, it is still discretized since the part becomes narrower
            // between the two points. As such it may need different beadings along the way.
            let left_point = vu::get_source_point(vd, left_cell, points, segments);
            let right_point = vu::get_source_point(vd, right_cell, points, segments);
            let d = v_size(right_point - left_point);
            let middle = (left_point + right_point) / 2;
            let x_axis_dir = turn90_ccw(right_point - left_point);
            let x_axis_length = v_size(x_axis_dir);

            let projected_x = |from: Point2LL| -> Coord {
                // Project a point on the edge.
                let vec = from - middle;
                dot(vec, x_axis_dir) / x_axis_length
            };

            let start_x = projected_x(start);
            let end_x = projected_x(end);

            // Part of the edge will be bound to the markings on the endpoints of the edge. Calculate how far that is.
            let bound = 0.5 / ((std::f64::consts::PI - self.transitioning_angle.value()) * 0.5).tan();
            let mut marking_start_x = (-d as f64 * bound) as Coord;
            let mut marking_end_x = (d as f64 * bound) as Coord;
            let mut marking_start = middle + x_axis_dir * marking_start_x / x_axis_length;
            let mut marking_end = middle + x_axis_dir * marking_end_x / x_axis_length;
            let mut direction: Coord = 1;

            if start_x > end_x {
                // Oops, the Voronoi edge is the other way around.
                direction = -1;
                std::mem::swap(&mut marking_start, &mut marking_end);
                std::mem::swap(&mut marking_start_x, &mut marking_end_x);
            }

            // Start generating points along the edge.
            let a = start;
            let b = end;
            let mut ret = vec![a];

            // Introduce an extra edge at the borders of the markings?
            let mut add_marking_start = marking_start_x * direction > start_x * direction;
            let mut add_marking_end = marking_end_x * direction > start_x * direction;

            // The edge's length may not be divisible by the step size, so calculate an integer step count and evenly distribute the vertices among those.
            let ab = b - a;
            let ab_size = v_size(ab);
            let mut step_count = (ab_size + self.discretization_step_size / 2) / self.discretization_step_size;
            if step_count % 2 == 1 {
                step_count += 1; // enforce a discretization point being added in the middle
            }
            for step in 1..step_count {
                let here = a + ab * step / step_count; // Now simply interpolate the coordinates to get the new vertices!
                let x_here = projected_x(here); // If we've surpassed the position of the extra markings, we may need to insert them first.
                if add_marking_start && marking_start_x * direction < x_here * direction {
                    ret.push(marking_start);
                    add_marking_start = false;
                }
                if add_marking_end && marking_end_x * direction < x_here * direction {
                    ret.push(marking_end);
                    add_marking_end = false;
                }
                ret.push(here);
            }
            if add_marking_end && marking_end_x * direction < end_x * direction {
                ret.push(marking_end);
            }
            ret.push(b);
            ret
        }
    }

    /// Compute the range of line segments that surround a cell of the skeletal graph that belongs to a point on the medial axis.
    #[allow(clippy::too_many_arguments)]
    fn compute_point_cell_range(
        &self,
        vd: &VoronoiDiagram,
        cell: usize,
        start_source_point: &mut Point2LL,
        end_source_point: &mut Point2LL,
        starting_vd_edge: &mut usize,
        ending_vd_edge: &mut usize,
        points: &[Point2LL],
        segments: &[Segment],
    ) -> bool {
        let incident = vd.cell(cell).incident_edge();
        if vd.is_infinite(incident) {
            return false; // Infinite edges only occur outside of the polygon. Don't copy any part of this cell.
        }
        // Check if any point of the cell is inside or outside polygon
        // Copy whole cell into graph or not at all

        let source_point = vu::get_source_point(vd, cell, points, segments);
        let source_point_index = vu::get_source_point_index(vd, cell, points, segments);
        let mut some_point = vu::p(vd, vd.edge(incident).vertex0());
        if some_point == source_point {
            some_point = vu::p(vd, vd.vertex1(incident));
        }
        // Test if the some_point is even inside the polygon.
        if !linear_alg_2d::is_inside_corner(source_point_index.prev().p(), source_point_index.p(), source_point_index.next().p(), some_point) {
            return false; // Don't copy any part of this cell
        }
        let mut vd_edge = incident;
        loop {
            let p1 = vu::p(vd, vd.vertex1(vd_edge));
            if p1 == source_point {
                *start_source_point = source_point;
                *end_source_point = source_point;
                *starting_vd_edge = vd.edge(vd_edge).next();
                *ending_vd_edge = vd_edge;
            }
            vd_edge = vd.edge(vd_edge).next();
            if vd_edge == incident {
                break;
            }
        }
        true
    }

    /// Compute the range of line segments that surround a cell of the skeletal graph that belongs to a line segment of the medial axis.
    #[allow(clippy::too_many_arguments)]
    fn compute_segment_cell_range(
        &self,
        vd: &VoronoiDiagram,
        cell: usize,
        start_source_point: &mut Point2LL,
        end_source_point: &mut Point2LL,
        starting_vd_edge: &mut usize,
        ending_vd_edge: &mut usize,
        points: &[Point2LL],
        segments: &[Segment],
    ) {
        let source_segment = vu::get_source_segment(vd, cell, points, segments);
        let from = source_segment.from();
        let to = source_segment.to();

        // Find starting edge
        // Find end edge
        let mut seen_possible_start = false;
        let mut after_start = false;
        let mut ending_edge_is_set_before_start = false;
        let incident = vd.cell(cell).incident_edge();
        let mut edge = incident;
        loop {
            if !vd.is_infinite(edge) {
                let v0 = vu::p(vd, vd.edge(edge).vertex0());
                let v1 = vu::p(vd, vd.vertex1(edge));
                if v0 == to && !after_start {
                    // Use the last edge which starts in source_segment.to
                    *starting_vd_edge = edge;
                    seen_possible_start = true;
                } else if seen_possible_start {
                    after_start = true;
                }

                if v1 == from && (*ending_vd_edge == NIL || ending_edge_is_set_before_start) {
                    ending_edge_is_set_before_start = !after_start;
                    *ending_vd_edge = edge;
                }
            }
            edge = vd.edge(edge).next();
            if edge == incident {
                break;
            }
        }

        *start_source_point = source_segment.to();
        *end_source_point = source_segment.from();
    }

    /// Compute the skeletal trapezoidation decomposition of the input shape.
    fn construct_from_polygons(&mut self, polys: &Shape) {
        let points: Vec<Point2LL> = Vec::new(); // Remains empty

        let mut segments: Vec<Segment> = Vec::new();
        for poly_idx in 0..polys.len() {
            let poly = &polys[poly_idx];
            for point_idx in 0..poly.len() {
                segments.push(Segment::new(polys as *const Shape, poly_idx, point_idx));
            }
        }

        // construct_voronoi(segments...) with CuraEngine's segment traits: low = to(), high = from().
        let mut vd = VoronoiDiagram::new();
        {
            let mut builder = VoronoiBuilder::new();
            for s in &segments {
                let low = s.to();
                let high = s.from();
                builder.insert_segment(low.x as i32, low.y as i32, high.x as i32, high.y as i32);
            }
            builder.construct(&mut vd);
        }

        self.vd_edge_to_he_edge = vec![NIL; vd.num_edges()];
        self.vd_node_to_he_node = vec![NIL; vd.num_vertices()];

        for cell in 0..vd.num_cells() {
            if vd.cell(cell).incident_edge() == NIL {
                // There is no spoon
                continue;
            }
            let mut start_source_point = Point2LL::new(0, 0);
            let mut end_source_point = Point2LL::new(0, 0);
            let mut starting_vonoroi_edge = NIL;
            let mut ending_vonoroi_edge = NIL;
            // Compute and store result in above variables

            if vd.cell(cell).contains_point() {
                let keep_going = self.compute_point_cell_range(
                    &vd,
                    cell,
                    &mut start_source_point,
                    &mut end_source_point,
                    &mut starting_vonoroi_edge,
                    &mut ending_vonoroi_edge,
                    &points,
                    &segments,
                );
                if !keep_going {
                    continue;
                }
            } else {
                self.compute_segment_cell_range(
                    &vd,
                    cell,
                    &mut start_source_point,
                    &mut end_source_point,
                    &mut starting_vonoroi_edge,
                    &mut ending_vonoroi_edge,
                    &points,
                    &segments,
                );
            }

            if starting_vonoroi_edge == NIL || ending_vonoroi_edge == NIL {
                continue;
            }

            // Copy start to end edge to graph
            let mut prev_edge = NIL;
            let to_p = vu::p(&vd, vd.vertex1(starting_vonoroi_edge));
            self.transfer_edge(
                &vd,
                start_source_point,
                to_p,
                starting_vonoroi_edge,
                &mut prev_edge,
                start_source_point,
                end_source_point,
                &points,
                &segments,
            );
            let starting_node = self.vd_node_to_he_node[vd.edge(starting_vonoroi_edge).vertex0()];
            self.graph.nodes[starting_node].data.distance_to_boundary = 0;

            self.graph.make_rib(&mut prev_edge, start_source_point, end_source_point);
            let mut vd_edge = vd.edge(starting_vonoroi_edge).next();
            while vd_edge != ending_vonoroi_edge {
                let v1 = vu::p(&vd, vd.edge(vd_edge).vertex0());
                let v2 = vu::p(&vd, vd.vertex1(vd_edge));
                self.transfer_edge(&vd, v1, v2, vd_edge, &mut prev_edge, start_source_point, end_source_point, &points, &segments);

                self.graph.make_rib(&mut prev_edge, start_source_point, end_source_point);
                vd_edge = vd.edge(vd_edge).next();
            }

            let from_p = vu::p(&vd, vd.edge(ending_vonoroi_edge).vertex0());
            self.transfer_edge(
                &vd,
                from_p,
                end_source_point,
                ending_vonoroi_edge,
                &mut prev_edge,
                start_source_point,
                end_source_point,
                &points,
                &segments,
            );
            let to_node = self.graph.edges[prev_edge].to;
            self.graph.nodes[to_node].data.distance_to_boundary = 0;
        }

        self.separate_pointy_quad_end_nodes();

        self.graph.collapse_small_edges(5);

        // Set [incident_edge] the the first possible edge that way we can iterate over all reachable edges from node.incident_edge,
        // without needing to iterate backward
        let mut e = self.graph.edges.first();
        while e != NIL {
            if self.graph.edges[e].prev == NIL {
                let f = self.graph.edges[e].from;
                self.graph.nodes[f].incident_edge = e;
            }
            e = self.graph.edges.next(e);
        }
    }

    /// For VD cells associated with an input polygon vertex, we need to separate the node at the end and start of the cell into two.
    fn separate_pointy_quad_end_nodes(&mut self) {
        let mut visited_nodes: HashSet<usize> = HashSet::new();
        let mut e = self.graph.edges.first();
        while e != NIL {
            if self.graph.edges[e].prev == NIL {
                let quad_start = e;
                let from = self.graph.edges[quad_start].from;
                if !visited_nodes.contains(&from) {
                    visited_nodes.insert(from);
                } else {
                    // Needs to be duplicated
                    let copy = self.graph.nodes[from].clone();
                    let new_node = self.graph.nodes.push_back(copy);
                    self.graph.nodes[new_node].incident_edge = quad_start;
                    self.graph.edges[quad_start].from = new_node;
                    let t = self.graph.edges[quad_start].twin;
                    self.graph.edges[t].to = new_node;
                }
            }
            e = self.graph.edges.next(e);
        }
    }

    // =====================================================================================
    //    TRANSITIONING
    // =====================================================================================

    /// Generate the paths that the printer must extrude, to print the outlines in the input polygons.
    pub fn generate_toolpaths(&mut self, generated_toolpaths: &mut Vec<VariableWidthLines>, filter_outermost_central_edges: bool) {
        self.generated_toolpaths = std::mem::take(generated_toolpaths);

        self.update_is_central();

        self.filter_central(CENTRAL_FILTER_DIST);

        if filter_outermost_central_edges {
            self.filter_outer_central();
        }

        self.update_bead_count();

        self.filter_noncentral_regions();

        self.generate_transitioning_ribs();

        self.generate_extra_ribs();

        self.generate_segments();

        *generated_toolpaths = std::mem::take(&mut self.generated_toolpaths);
    }

    #[inline]
    fn has_transitions(&self, e: usize, ignore_empty: bool) -> bool {
        let t = self.graph.edges[e].data.transitions;
        t != NIL && (ignore_empty || !self.transitions_store[t].is_empty())
    }

    #[inline]
    fn has_transition_ends(&self, e: usize, ignore_empty: bool) -> bool {
        let t = self.graph.edges[e].data.transition_ends;
        t != NIL && (ignore_empty || !self.transition_ends_store[t].is_empty())
    }

    #[inline]
    fn has_extrusion_junctions(&self, e: usize, ignore_empty: bool) -> bool {
        let t = self.graph.edges[e].data.extrusion_junctions;
        t != NIL && (ignore_empty || !self.junctions_store[t].is_empty())
    }

    #[inline]
    fn has_beading(&self, n: usize) -> bool {
        self.graph.nodes[n].data.beading != NIL
    }

    /// Update the "is_central" flag for each edge based on the transitioning_angle.
    fn update_is_central(&mut self) {
        let outer_edge_filter_length = self.beading_strategy.get_transition_thickness(0) / 2;

        let cap = (self.beading_strategy.get_transitioning_angle().value() * 0.5).sin(); // = cos(bisector_angle / 2)
        let mut e = self.graph.edges.first();
        while e != NIL {
            let g = &self.graph;
            let twin = g.edges[e].twin;
            let central: Option<bool> = if twin == NIL {
                crate::log_warn!("Encountered a Voronoi edge without twin!");
                None
            } else if g.edges[twin].data.central_is_set() {
                Some(g.edges[twin].data.is_central())
            } else if g.edges[e].data.type_ == EdgeType::ExtraVd {
                Some(false)
            } else if g.from_dtb(e).max(g.to_dtb(e)) < outer_edge_filter_length {
                Some(false)
            } else {
                let a = g.from_p(e);
                let b = g.to_p(e);
                let ab = b - a;
                let d_r = (g.to_dtb(e) - g.from_dtb(e)).abs();
                let d_d = v_size(ab);
                Some((d_r as f64) < d_d as f64 * cap)
            };
            if let Some(c) = central {
                self.graph.edges[e].data.set_is_central(c);
            }
            e = self.graph.edges.next(e);
        }
    }

    /// Filter out small central areas.
    fn filter_central(&mut self, max_length: Coord) {
        let mut e = self.graph.edges.first();
        while e != NIL {
            let to = self.graph.edges[e].to;
            if self.is_end_of_central(e) && self.graph.node_is_local_maximum(to, false) && !self.graph.node_is_local_maximum(to, false) {
                let twin = self.graph.edges[e].twin;
                self.filter_central_rec(twin, 0, max_length);
            }
            e = self.graph.edges.next(e);
        }
    }

    fn filter_central_rec(&mut self, starting_edge: usize, traveled_dist: Coord, max_length: Coord) -> bool {
        let length = v_size(self.graph.from_p(starting_edge) - self.graph.to_p(starting_edge));
        if traveled_dist + length > max_length {
            return false;
        }

        let mut should_dissolve = true; // Should we unmark this as central and propagate that?
        let twin = self.graph.edges[starting_edge].twin;
        let mut next_edge = self.graph.edges[starting_edge].next;
        while next_edge != NIL && next_edge != twin {
            if self.graph.is_central(next_edge) {
                should_dissolve &= self.filter_central_rec(next_edge, traveled_dist + length, max_length);
            }
            next_edge = self.graph.twin_next(next_edge);
        }

        should_dissolve &= !self.graph.node_is_local_maximum(self.graph.edges[starting_edge].to, false); // Don't filter central regions with a local maximum!
        if should_dissolve {
            self.graph.edges[starting_edge].data.set_is_central(false);
            self.graph.edges[twin].data.set_is_central(false);
        }
        should_dissolve
    }

    /// Unmark the outermost edges directly connected to the outline, as not being central.
    fn filter_outer_central(&mut self) {
        let mut e = self.graph.edges.first();
        while e != NIL {
            if self.graph.edges[e].prev == NIL {
                self.graph.edges[e].data.set_is_central(false);
                let t = self.graph.edges[e].twin;
                self.graph.edges[t].data.set_is_central(false);
            }
            e = self.graph.edges.next(e);
        }
    }

    /// Set bead count in central regions based on the optimal_bead_count of the beading strategy.
    fn update_bead_count(&mut self) {
        let mut e = self.graph.edges.first();
        while e != NIL {
            if self.graph.is_central(e) {
                let to = self.graph.edges[e].to;
                let dtb = self.graph.nodes[to].data.distance_to_boundary;
                self.graph.nodes[to].data.bead_count = self.beading_strategy.get_optimal_bead_count(dtb * 2);
            }
            e = self.graph.edges.next(e);
        }

        // Fix bead count at locally maximal R, also for central regions!! See TODO s in generateTransitionEnd(.)
        let mut n = self.graph.nodes.first();
        while n != NIL {
            if self.graph.node_is_local_maximum(n, false) {
                if self.graph.nodes[n].data.distance_to_boundary < 0 {
                    crate::log_warn!("Distance to boundary not yet computed for local maximum!");
                    self.graph.nodes[n].data.distance_to_boundary = Coord::MAX;
                    let incident = self.graph.nodes[n].incident_edge;
                    let mut edge = incident;
                    loop {
                        let g = &self.graph;
                        let cand = g.to_dtb(edge) + v_size(g.from_p(edge) - g.to_p(edge));
                        let cur = self.graph.nodes[n].data.distance_to_boundary;
                        self.graph.nodes[n].data.distance_to_boundary = if cand < cur { cand } else { cur };
                        edge = self.graph.twin_next(edge);
                        if edge == incident {
                            break;
                        }
                    }
                }
                let dtb = self.graph.nodes[n].data.distance_to_boundary;
                let bead_count = self.beading_strategy.get_optimal_bead_count(dtb * 2);
                self.graph.nodes[n].data.bead_count = bead_count;
            }
            n = self.graph.nodes.next(n);
        }
    }

    /// Add central regions and set bead counts where there is an end of the central area and when traveling upward we get to another region with the same bead count.
    fn filter_noncentral_regions(&mut self) {
        let mut e = self.graph.edges.first();
        while e != NIL {
            if self.is_end_of_central(e) {
                let to = self.graph.edges[e].to;
                if self.graph.nodes[to].data.bead_count < 0 && self.graph.nodes[to].data.distance_to_boundary != 0 {
                    crate::log_warn!("Encountered an uninitialized bead at the boundary!");
                }
                const MAX_DIST: Coord = 400;
                let bc = self.graph.nodes[to].data.bead_count;
                self.filter_noncentral_regions_rec(e, bc, 0, MAX_DIST);
            }
            e = self.graph.edges.next(e);
        }
    }

    fn filter_noncentral_regions_rec(&mut self, to_edge: usize, bead_count: Coord, traveled_dist: Coord, max_dist: Coord) -> bool {
        let g = &self.graph;
        let r = g.to_dtb(to_edge);

        let twin = g.edges[to_edge].twin;
        let mut next_edge = g.edges[to_edge].next;
        while next_edge != NIL && next_edge != twin {
            if g.to_dtb(next_edge) >= r || shorter_then(g.to_p(next_edge) - g.from_p(next_edge), 10) {
                break; // Only walk upward
            }
            next_edge = g.twin_next(next_edge);
        }
        if next_edge == twin || next_edge == NIL {
            return false;
        }

        let length = v_size(g.to_p(next_edge) - g.from_p(next_edge));

        let next_to = g.edges[next_edge].to;
        let next_bc = g.nodes[next_to].data.bead_count;
        let dissolve = if next_bc == bead_count {
            true
        } else if next_bc < 0 {
            self.filter_noncentral_regions_rec(next_edge, bead_count, traveled_dist + length, max_dist)
        } else {
            // Upward bead count is different
            // Dissolve if two central regions with different bead count are closer together than the max_dist (= transition distance)
            (traveled_dist + length < max_dist) && (next_bc - bead_count).abs() == 1
        };

        if dissolve {
            self.graph.edges[next_edge].data.set_is_central(true);
            let nt = self.graph.edges[next_edge].twin;
            self.graph.edges[nt].data.set_is_central(true);
            let dtb = self.graph.nodes[next_to].data.distance_to_boundary;
            self.graph.nodes[next_to].data.bead_count = self.beading_strategy.get_optimal_bead_count(dtb * 2);
            self.graph.nodes[next_to].data.transition_ratio = 0.0;
        }
        dissolve // Dissolving only depend on the one edge going upward. There cannot be multiple edges going upward.
    }

    fn generate_transitioning_ribs(&mut self) {
        // Store the upward edges to the transitions.
        self.transitions_store.clear();
        self.transition_ends_store.clear();
        self.generate_transition_mids();

        self.filter_transition_mids();

        self.generate_all_transition_ends();

        self.apply_transitions();

        // Note that the shared pointer lists will be out of scope and thus destroyed here, since the remaining refs are weak_ptr.
        self.transitions_store.clear();
        self.transition_ends_store.clear();
        let mut e = self.graph.edges.first();
        while e != NIL {
            self.graph.edges[e].data.transitions = NIL;
            self.graph.edges[e].data.transition_ends = NIL;
            e = self.graph.edges.next(e);
        }
    }

    /// Generate middle points of all transitions on edges.
    fn generate_transition_mids(&mut self) {
        let mut e = self.graph.edges.first();
        while e != NIL {
            if self.graph.is_central(e) {
                self.generate_transition_mids_for_edge(e);
            }
            e = self.graph.edges.next(e);
        }
    }

    fn generate_transition_mids_for_edge(&mut self, e: usize) {
        let g = &self.graph;
        let start_r = g.from_dtb(e);
        let end_r = g.to_dtb(e);
        let from = g.edges[e].from;
        let to = g.edges[e].to;
        let start_bead_count = g.nodes[from].data.bead_count as i32;
        let end_bead_count = g.nodes[to].data.bead_count as i32;

        if start_r == end_r {
            // No transitions occur when both end points have the same distance_to_boundary
            if g.nodes[from].data.bead_count != g.nodes[to].data.bead_count {
                crate::log_warn!(
                    "Bead count {} is different from {} even though distance to boundary is the same.",
                    g.nodes[from].data.bead_count,
                    g.nodes[to].data.bead_count
                );
            }
            return;
        } else if start_r > end_r {
            // Only consider those half-edges which are going from a lower to a higher distance_to_boundary
            return;
        }

        if g.nodes[from].data.bead_count == g.nodes[to].data.bead_count {
            // No transitions should occur according to the enforced bead counts
            return;
        }

        if start_bead_count as Coord > self.beading_strategy.get_optimal_bead_count(start_r * 2)
            || end_bead_count as Coord > self.beading_strategy.get_optimal_bead_count(end_r * 2)
        {
            // Wasn't the case earlier in this function because of already introduced transitions
            crate::log_error!("transitioning segment overlap!");
        }
        let edge_size = v_size(g.from_p(e) - g.to_p(e));
        for transition_lower_bead_count in start_bead_count..end_bead_count {
            let mut mid_r = self.beading_strategy.get_transition_thickness(transition_lower_bead_count as Coord) / 2;
            if mid_r > end_r {
                crate::log_error!("transition on segment lies outside of segment!");
                mid_r = end_r;
            }
            if mid_r < start_r {
                crate::log_error!("transition on segment lies outside of segment!");
                mid_r = start_r;
            }
            let mid_pos = edge_size * (mid_r - start_r) / (end_r - start_r);
            if !self.has_transitions(e, true) {
                self.transitions_store.push(IndexList::new());
                self.graph.edges[e].data.transitions = self.transitions_store.len() - 1; // initialization
            }
            let t = self.graph.edges[e].data.transitions;
            self.transitions_store[t].push_back(TransitionMiddle { pos: mid_pos, lower_bead_count: transition_lower_bead_count, feature_radius: mid_r });
        }
    }

    fn erase_transition_ref(&mut self, r: &TransitionMidRef) {
        let t = self.graph.edges[r.edge].data.transitions;
        if self.transitions_store[t].is_alive(r.transition_it) {
            self.transitions_store[t].erase(r.transition_it);
        }
    }

    /// Removes some transition middle points.
    fn filter_transition_mids(&mut self) {
        let mut e = self.graph.edges.first();
        while e != NIL {
            self.filter_transition_mids_for_edge(e);
            e = self.graph.edges.next(e);
        }
    }

    fn filter_transition_mids_for_edge(&mut self, edge: usize) {
        if !self.has_transitions(edge, false) {
            return;
        }
        let t = self.graph.edges[edge].data.transitions;

        let a = self.graph.from_p(edge);
        let b = self.graph.to_p(edge);
        let ab = b - a;
        let ab_size = v_size(ab);

        let mut going_up = true;
        let back = *self.transitions_store[t].back();
        let to_be_dissolved_back =
            self.dissolve_nearby_transitions(edge, &back, ab_size - back.pos, self.transition_filter_dist, going_up);
        let mut should_dissolve_back = !to_be_dissolved_back.is_empty();
        for r in &to_be_dissolved_back {
            let back_bc = self.transitions_store[t].back().lower_bead_count as Coord;
            self.dissolve_bead_count_region(edge, back_bc + 1, back_bc);
            self.erase_transition_ref(r);
        }

        {
            let back = *self.transitions_store[t].back();
            let trans_bead_count = back.lower_bead_count as Coord;
            let upper_transition_half_length = ((1.0 - self.beading_strategy.get_transition_anchor_pos(trans_bead_count))
                * self.beading_strategy.get_transitioning_length(trans_bead_count) as f64) as Coord;
            should_dissolve_back |= self.filter_end_of_central_transition(edge, ab_size - back.pos, upper_transition_half_length, trans_bead_count);
        }

        if should_dissolve_back {
            self.transitions_store[t].pop_back();
        }
        if self.transitions_store[t].is_empty() {
            // FilterEndOfCentralTransition gives inconsistent new bead count when executing for the same transition in two directions.
            return;
        }

        going_up = false;
        let twin = self.graph.edges[edge].twin;
        let front = *self.transitions_store[t].front();
        let to_be_dissolved_front = self.dissolve_nearby_transitions(twin, &front, front.pos, self.transition_filter_dist, going_up);
        let mut should_dissolve_front = !to_be_dissolved_front.is_empty();
        for r in &to_be_dissolved_front {
            let front_bc = self.transitions_store[t].front().lower_bead_count as Coord;
            self.dissolve_bead_count_region(twin, front_bc, front_bc + 1);
            self.erase_transition_ref(r);
        }

        {
            let front = *self.transitions_store[t].front();
            let trans_bead_count = front.lower_bead_count as Coord;
            let lower_transition_half_length = (self.beading_strategy.get_transition_anchor_pos(trans_bead_count)
                * self.beading_strategy.get_transitioning_length(trans_bead_count) as f64) as Coord;
            should_dissolve_front |= self.filter_end_of_central_transition(twin, front.pos, lower_transition_half_length, trans_bead_count + 1);
        }

        if should_dissolve_front {
            self.transitions_store[t].pop_front();
        }
    }

    /// Merge transitions that are too close together.
    fn dissolve_nearby_transitions(
        &self,
        edge_to_start: usize,
        origin_transition: &TransitionMiddle,
        traveled_dist: Coord,
        max_dist: Coord,
        going_up: bool,
    ) -> Vec<TransitionMidRef> {
        let mut to_be_dissolved: Vec<TransitionMidRef> = Vec::new();
        if traveled_dist > max_dist {
            return to_be_dissolved;
        }
        let g = &self.graph;
        let mut should_dissolve = true;
        let twin = g.edges[edge_to_start].twin;
        let mut edge = g.edges[edge_to_start].next;
        while edge != NIL && edge != twin {
            if !g.is_central(edge) {
                edge = g.twin_next(edge);
                continue;
            }

            let a = g.from_p(edge);
            let b = g.to_p(edge);
            let ab = b - a;
            let ab_size = v_size(ab);
            let is_aligned = g.is_upward(edge, false);
            let aligned_edge = if is_aligned { edge } else { g.edges[edge].twin };
            let mut seen_transition_on_this_edge = false;

            let origin_radius = origin_transition.feature_radius;
            let radius_here = g.from_dtb(edge);
            let dissolve_result_is_odd = (origin_transition.lower_bead_count % 2 != 0) == going_up;
            let width_deviation = (origin_radius - radius_here).abs() * 2; // times by two because the deviation happens at both sides of the significant edge
            let line_width_deviation = if dissolve_result_is_odd { width_deviation } else { width_deviation / 2 }; // assume the deviation will be split over either 1 or 2 lines, i.e. assume wall_distribution_count = 1
            if line_width_deviation > self.allowed_filter_deviation {
                should_dissolve = false;
            }

            if should_dissolve && self.has_transitions(aligned_edge, false) {
                let t = g.edges[aligned_edge].data.transitions;
                let list = &self.transitions_store[t];
                let mut it = list.first();
                while it != NIL {
                    // Note: this is not necessarily iterating in the traveling direction!
                    // Check whether we should dissolve
                    let tr = list[it];
                    let pos = if is_aligned { tr.pos } else { ab_size - tr.pos };
                    if traveled_dist + pos < max_dist && tr.lower_bead_count == origin_transition.lower_bead_count {
                        // Only dissolve local optima
                        to_be_dissolved.push(TransitionMidRef { edge: aligned_edge, transition_it: it });
                        seen_transition_on_this_edge = true;
                    }
                    it = list.next(it);
                }
            }
            if should_dissolve && !seen_transition_on_this_edge {
                let to_be_dissolved_here = self.dissolve_nearby_transitions(edge, origin_transition, traveled_dist + ab_size, max_dist, going_up);
                if to_be_dissolved_here.is_empty() {
                    // The region is too long to be dissolved in this direction, so it cannot be dissolved in any direction.
                    to_be_dissolved.clear();
                    return to_be_dissolved;
                }
                to_be_dissolved.extend(to_be_dissolved_here); // Transfer to_be_dissolved_here into to_be_dissolved
                should_dissolve = should_dissolve && !to_be_dissolved.is_empty();
            }
            edge = g.twin_next(edge);
        }

        if !should_dissolve {
            to_be_dissolved.clear();
        }

        to_be_dissolved
    }

    /// Spread a certain bead count over a region in the graph.
    fn dissolve_bead_count_region(&mut self, edge_to_start: usize, from_bead_count: Coord, to_bead_count: Coord) {
        let to = self.graph.edges[edge_to_start].to;
        if self.graph.nodes[to].data.bead_count != from_bead_count {
            return;
        }

        self.graph.nodes[to].data.bead_count = to_bead_count;
        let twin = self.graph.edges[edge_to_start].twin;
        let mut edge = self.graph.edges[edge_to_start].next;
        while edge != NIL && edge != twin {
            if self.graph.is_central(edge) {
                self.dissolve_bead_count_region(edge, from_bead_count, to_bead_count);
            }
            edge = self.graph.twin_next(edge);
        }
    }

    /// Change the bead count if the given edge is at the end of a central region.
    fn filter_end_of_central_transition(&mut self, edge_to_start: usize, traveled_dist: Coord, max_dist: Coord, replacing_bead_count: Coord) -> bool {
        if traveled_dist > max_dist {
            return false;
        }

        let mut is_end_of_central = true;
        let mut should_dissolve = false;
        let twin = self.graph.edges[edge_to_start].twin;
        let mut next_edge = self.graph.edges[edge_to_start].next;
        while next_edge != NIL && next_edge != twin {
            if self.graph.is_central(next_edge) {
                let length = v_size(self.graph.to_p(next_edge) - self.graph.from_p(next_edge));
                should_dissolve |= self.filter_end_of_central_transition(next_edge, traveled_dist + length, max_dist, replacing_bead_count);
                is_end_of_central = false;
            }
            next_edge = self.graph.twin_next(next_edge);
        }
        if is_end_of_central && traveled_dist < max_dist {
            should_dissolve = true;
        }

        if should_dissolve {
            let to = self.graph.edges[edge_to_start].to;
            self.graph.nodes[to].data.bead_count = replacing_bead_count;
        }
        should_dissolve
    }

    /// Generate the endpoints of all transitions for all edges in the graph.
    fn generate_all_transition_ends(&mut self) {
        let mut e = self.graph.edges.first();
        while e != NIL {
            if self.has_transitions(e, false) {
                let t = self.graph.edges[e].data.transitions;
                let mids: Vec<TransitionMiddle> = self.transitions_store[t].iter().copied().collect();
                for transition_middle in mids {
                    self.generate_transition_ends(e, transition_middle.pos, transition_middle.lower_bead_count as Coord);
                }
            }
            e = self.graph.edges.next(e);
        }
    }

    /// Generate the endpoints of a specific transition midpoint.
    fn generate_transition_ends(&mut self, edge: usize, mid_pos: Coord, lower_bead_count: Coord) {
        let a = self.graph.from_p(edge);
        let b = self.graph.to_p(edge);
        let ab = b - a;
        let ab_size = v_size(ab);

        let transition_length = self.beading_strategy.get_transitioning_length(lower_bead_count);
        let transition_mid_position = self.beading_strategy.get_transition_anchor_pos(lower_bead_count);
        const INNER_BEAD_WIDTH_RATIO_AFTER_TRANSITION: f64 = 1.0;

        let start_rest = 0.0;
        let mid_rest = transition_mid_position * INNER_BEAD_WIDTH_RATIO_AFTER_TRANSITION;
        let end_rest = INNER_BEAD_WIDTH_RATIO_AFTER_TRANSITION;

        {
            // Lower bead count transition end
            let start_pos = ab_size - mid_pos;
            let transition_half_length = (transition_mid_position * transition_length as f64) as Coord;
            let end_pos = start_pos + transition_half_length;
            let twin = self.graph.edges[edge].twin;
            self.generate_transition_end(twin, start_pos, end_pos, transition_half_length, mid_rest, start_rest, lower_bead_count);
        }

        {
            // Upper bead count transition end
            let start_pos = mid_pos;
            let transition_half_length = ((1.0 - transition_mid_position) * transition_length as f64) as Coord;
            let end_pos = mid_pos + transition_half_length;
            self.generate_transition_end(edge, start_pos, end_pos, transition_half_length, mid_rest, end_rest, lower_bead_count);
        }
    }

    /// Compute a single endpoint of a transition. Returns whether the given edge is going downward.
    #[allow(clippy::too_many_arguments)]
    fn generate_transition_end(
        &mut self,
        edge: usize,
        start_pos: Coord,
        end_pos: Coord,
        transition_half_length: Coord,
        start_rest: f64,
        end_rest: f64,
        lower_bead_count: Coord,
    ) -> bool {
        let a = self.graph.from_p(edge);
        let b = self.graph.to_p(edge);
        let ab = b - a;
        let ab_size = v_size(ab); // TODO: prevent recalculation of these values

        if start_pos > ab_size {
            crate::log_warn!("Start position of edge is beyond edge range.");
        }

        let going_up = end_rest > start_rest;

        if !self.graph.is_central(edge) {
            crate::log_warn!("This function shouldn't generate ends in or beyond non-central regions.");
            return false;
        }

        if end_pos > ab_size {
            // Recurse on all further edges
            let rest = end_rest - (start_rest - end_rest) * (end_pos - ab_size) as f64 / (start_pos - end_pos) as f64;

            let twin = self.graph.edges[edge].twin;
            let mut central_edge_count: Coord = 0;
            let mut outgoing = self.graph.edges[edge].next;
            while outgoing != NIL && outgoing != twin {
                if self.graph.is_central(outgoing) {
                    central_edge_count += 1;
                }
                outgoing = self.graph.twin_next(outgoing);
            }

            let mut is_only_going_down = true;
            let mut has_recursed = false;
            let mut outgoing = self.graph.edges[edge].next;
            while outgoing != NIL && outgoing != twin {
                let next = self.graph.twin_next(outgoing); // Before we change the outgoing edge itself
                if !self.graph.is_central(outgoing) {
                    outgoing = next;
                    continue; // Don't put transition ends in non-central regions
                }
                if central_edge_count > 1 && going_up && self.is_going_down(outgoing, 0, end_pos - ab_size + transition_half_length, lower_bead_count) {
                    // We're after a 3-way_all-central_junction-node and going in the direction of lower bead count
                    // don't introduce a transition end along this central direction, because this direction is the downward direction
                    // while we are supposed to be [going_up]
                    outgoing = next;
                    continue;
                }
                let is_going_down =
                    self.generate_transition_end(outgoing, 0, end_pos - ab_size, transition_half_length, rest, end_rest, lower_bead_count);
                is_only_going_down &= is_going_down;
                outgoing = next;
                has_recursed = true;
            }
            if !going_up || (has_recursed && !is_only_going_down) {
                let to = self.graph.edges[edge].to;
                self.graph.nodes[to].data.transition_ratio = rest;
                self.graph.nodes[to].data.bead_count = lower_bead_count;
            }
            is_only_going_down
        } else {
            // Add transition end point here
            let is_lower_end = end_rest == 0.0; // TODO collapse this parameter into the bool for which it is used here!

            let (upward_edge, pos) =
                if self.graph.is_upward(edge, false) { (edge, end_pos) } else { (self.graph.edges[edge].twin, ab_size - end_pos) };

            if !self.has_transition_ends(upward_edge, false) {
                // This edge doesn't have a data structure yet for the transition ends. Make one.
                self.transition_ends_store.push(IndexList::new());
                self.graph.edges[upward_edge].data.transition_ends = self.transition_ends_store.len() - 1;
            }
            let t = self.graph.edges[upward_edge].data.transition_ends;
            let transitions = &mut self.transition_ends_store[t];

            // Add a transition to it (on the correct side).
            let te = TransitionEnd { pos, lower_bead_count: lower_bead_count as i32, is_lower_end };
            if transitions.is_empty() || pos < transitions.front().pos {
                // Preorder so that sorting later on is faster
                transitions.push_front(te);
            } else {
                transitions.push_back(te);
            }
            false
        }
    }

    /// Determines whether an edge is going downwards or upwards in the graph.
    fn is_going_down(&self, outgoing: usize, traveled_dist: Coord, max_dist: Coord, lower_bead_count: Coord) -> bool {
        // NOTE: the logic below is not fully thought through.
        // TODO: take transition mids into account
        let g = &self.graph;
        if g.to_dtb(outgoing) == 0 {
            return true;
        }
        let is_upward = g.to_dtb(outgoing) >= g.from_dtb(outgoing);
        let upward_edge = if is_upward { outgoing } else { g.edges[outgoing].twin };
        let to = g.edges[outgoing].to;
        if g.nodes[to].data.bead_count > lower_bead_count + 1 {
            if !self.has_transitions(upward_edge, false) {
                crate::log_warn!("If the bead count is going down there has to be a transition mid!");
            }
            return false;
        }
        let length = v_size(g.to_p(outgoing) - g.from_p(outgoing));
        if self.has_transitions(upward_edge, false) {
            let t = g.edges[upward_edge].data.transitions;
            let transition_mids = &self.transitions_store[t];
            let mid = if is_upward { transition_mids.front() } else { transition_mids.back() };
            if mid.lower_bead_count as Coord == lower_bead_count
                && ((is_upward && mid.pos + traveled_dist < max_dist) || (!is_upward && length - mid.pos + traveled_dist < max_dist))
            {
                return true;
            }
        }
        if traveled_dist + length > max_dist {
            return false;
        }
        if g.nodes[to].data.bead_count <= lower_bead_count
            && !(g.nodes[to].data.bead_count == lower_bead_count && g.nodes[to].data.transition_ratio > 0.0)
        {
            return true;
        }

        let mut is_only_going_down = true;
        let mut has_recursed = false;
        let twin = g.edges[outgoing].twin;
        let mut next = g.edges[outgoing].next;
        while next != NIL && next != twin {
            if g.is_central(next) {
                let is_going_down = self.is_going_down(next, traveled_dist + length, max_dist, lower_bead_count);
                is_only_going_down &= is_going_down;
                has_recursed = true;
            }
            next = g.twin_next(next);
        }
        has_recursed && is_only_going_down
    }

    /// Also set the rest values at nodes in between the transition ends.
    fn apply_transitions(&mut self) {
        let mut e = self.graph.edges.first();
        while e != NIL {
            let twin = self.graph.edges[e].twin;
            if self.has_transition_ends(twin, false) {
                let length = v_size(self.graph.from_p(e) - self.graph.to_p(e));
                let tt = self.graph.edges[twin].data.transition_ends;
                if !self.has_transition_ends(e, false) {
                    self.transition_ends_store.push(IndexList::new());
                    self.graph.edges[e].data.transition_ends = self.transition_ends_store.len() - 1;
                }
                let te = self.graph.edges[e].data.transition_ends;
                let twin_ends: Vec<TransitionEnd> = self.transition_ends_store[tt].iter().copied().collect();
                for end in twin_ends {
                    self.transition_ends_store[te].push_back(TransitionEnd {
                        pos: length - end.pos,
                        lower_bead_count: end.lower_bead_count,
                        is_lower_end: end.is_lower_end,
                    });
                }
                self.transition_ends_store[tt].clear();
            }
            e = self.graph.edges.next(e);
        }

        let mut e = self.graph.edges.first();
        while e != NIL {
            if self.has_transition_ends(e, false) {
                let t = self.graph.edges[e].data.transition_ends;
                self.transition_ends_store[t].stable_sort_by(|a, b| a.pos < b.pos);

                let from = self.graph.edges[e].from;
                let to = self.graph.edges[e].to;
                let a = self.graph.nodes[from].p;
                let b = self.graph.nodes[to].p;
                let ab = b - a;
                let ab_size = v_size(ab);

                let mut last_edge_replacing_input = e;
                let ends: Vec<TransitionEnd> = self.transition_ends_store[t].iter().copied().collect();
                for transition_end in ends {
                    let new_node_bead_count = if transition_end.is_lower_end {
                        transition_end.lower_bead_count as Coord
                    } else {
                        transition_end.lower_bead_count as Coord + 1
                    };
                    let end_pos = transition_end.pos;
                    let close_node = if end_pos < ab_size / 2 { from } else { to };
                    if (end_pos < SNAP_DIST || end_pos > ab_size - SNAP_DIST) && self.graph.nodes[close_node].data.bead_count == new_node_bead_count {
                        self.graph.nodes[close_node].data.transition_ratio = 0.0;
                        continue;
                    }
                    let mid = a + normal(ab, end_pos);

                    last_edge_replacing_input = self.graph.insert_node(last_edge_replacing_input, mid, new_node_bead_count);
                }
            }
            e = self.graph.edges.next(e);
        }
    }

    /// Determines whether this edge marks the end of the central region.
    fn is_end_of_central(&self, edge_to: usize) -> bool {
        let g = &self.graph;
        if !g.is_central(edge_to) {
            return false;
        }
        if g.edges[edge_to].next == NIL {
            return true;
        }
        let twin = g.edges[edge_to].twin;
        let mut edge = g.edges[edge_to].next;
        while edge != NIL && edge != twin {
            if g.is_central(edge) {
                return false;
            }
            edge = g.twin_next(edge);
        }
        true
    }

    /// Create extra ribs in the graph where the graph contains a parabolic arc or a straight between two inner corners.
    fn generate_extra_ribs(&mut self) {
        let mut e = self.graph.edges.first();
        while e != NIL {
            let g = &self.graph;
            if !g.is_central(e) || shorter_then(g.to_p(e) - g.from_p(e), self.discretization_step_size) || g.from_dtb(e) >= g.to_dtb(e) {
                e = self.graph.edges.next(e);
                continue;
            }

            let rib_thicknesses = self.beading_strategy.get_nonlinear_thicknesses(g.nodes[g.edges[e].from].data.bead_count);

            if rib_thicknesses.is_empty() {
                e = self.graph.edges.next(e);
                continue;
            }

            // Preload some variables before [edge] gets changed
            let from = g.edges[e].from;
            let to = g.edges[e].to;
            let a = g.nodes[from].p;
            let b = g.nodes[to].p;
            let ab = b - a;
            let ab_size = v_size(ab);
            let a_r = g.nodes[from].data.distance_to_boundary;
            let b_r = g.nodes[to].data.distance_to_boundary;

            let mut last_edge_replacing_input = e;
            for rib_thickness in rib_thicknesses {
                if rib_thickness / 2 <= a_r {
                    continue;
                }
                if rib_thickness / 2 >= b_r {
                    break;
                }

                let g = &self.graph;
                let new_node_bead_count = g.nodes[g.edges[e].from].data.bead_count.min(g.nodes[g.edges[e].to].data.bead_count);
                let end_pos = ab_size * (rib_thickness / 2 - a_r) / (b_r - a_r);
                let close_node = if end_pos < ab_size / 2 { from } else { to };
                if (end_pos < SNAP_DIST || end_pos > ab_size - SNAP_DIST) && g.nodes[close_node].data.bead_count == new_node_bead_count {
                    self.graph.nodes[close_node].data.transition_ratio = 0.0;
                    continue;
                }
                let mid = a + normal(ab, end_pos);

                last_edge_replacing_input = self.graph.insert_node(last_edge_replacing_input, mid, new_node_bead_count);
            }
            e = self.graph.edges.next(e);
        }
    }

    // =====================================================================================
    //  TOOLPATH GENERATION
    // =====================================================================================

    fn generate_segments(&mut self) {
        let mut upward_quad_mids: Vec<usize> = Vec::new();
        let mut e = self.graph.edges.first();
        while e != NIL {
            let ed = &self.graph.edges[e];
            if ed.prev != NIL && ed.next != NIL && self.graph.is_upward(e, false) {
                upward_quad_mids.push(e);
            }
            e = self.graph.edges.next(e);
        }

        {
            let g = &self.graph;
            cppstd::stable_sort_by(&mut upward_quad_mids, |&a, &b| {
                if g.to_dtb(a) == g.to_dtb(b) {
                    // PathOrdering between two 'upward' edges of the same distance is important when one of the edges is flat and connected to the other
                    let a_flat = g.from_dtb(a) == g.to_dtb(a);
                    let b_flat = g.from_dtb(b) == g.to_dtb(b);
                    if a_flat && b_flat {
                        let max = Coord::MAX;
                        let min = |x: Coord, y: Coord| if y < x { y } else { x };
                        let a_dist_from_up = min(
                            g.dist_to_go_up(a).unwrap_or(max),
                            g.dist_to_go_up(g.edges[a].twin).unwrap_or(max),
                        ) - v_size(g.to_p(a) - g.from_p(a));
                        let b_dist_from_up = min(
                            g.dist_to_go_up(b).unwrap_or(max),
                            g.dist_to_go_up(g.edges[b].twin).unwrap_or(max),
                        ) - v_size(g.to_p(b) - g.from_p(b));
                        return a_dist_from_up < b_dist_from_up;
                    } else if a_flat {
                        return true; // Edge a might be 'above' edge b
                    } else if b_flat {
                        return false; // Edge b might be 'above' edge a
                    }
                    // PathOrdering is not important
                }
                g.to_dtb(a) > g.to_dtb(b)
            });
        }

        self.beadings_store.clear();
        {
            // Store beading
            let mut n = self.graph.nodes.first();
            while n != NIL {
                let data = self.graph.nodes[n].data.clone();
                if data.bead_count > 0 {
                    if data.transition_ratio == 0.0 {
                        let beading = self.beading_strategy.compute(data.distance_to_boundary * 2, data.bead_count);
                        if beading.total_thickness != data.distance_to_boundary * 2 {
                            crate::log_warn!("If transitioning to an endpoint (ratio 0), the node should be exactly in the middle.");
                        }
                        self.beadings_store.push(BeadingPropagation::new(beading));
                        self.graph.nodes[n].data.beading = self.beadings_store.len() - 1;
                    } else {
                        let low_count_beading = self.beading_strategy.compute(data.distance_to_boundary * 2, data.bead_count);
                        let high_count_beading = self.beading_strategy.compute(data.distance_to_boundary * 2, data.bead_count + 1);
                        let merged = self.interpolate(&low_count_beading, 1.0 - data.transition_ratio, &high_count_beading);
                        if merged.total_thickness != data.distance_to_boundary * 2 {
                            crate::log_warn!("If merging two beads, the new bead must be exactly in the middle.");
                        }
                        self.beadings_store.push(BeadingPropagation::new(merged));
                        self.graph.nodes[n].data.beading = self.beadings_store.len() - 1;
                    }
                }
                n = self.graph.nodes.next(n);
            }
        }

        self.propagate_beadings_upward(&upward_quad_mids);

        self.propagate_beadings_downward(&upward_quad_mids);

        self.junctions_store.clear();
        self.generate_junctions();

        self.connect_junctions();

        self.generate_local_maxima_single_beads();

        // The shared pointer storage goes out of scope here.
        self.beadings_store.clear();
        self.junctions_store.clear();
        let mut n = self.graph.nodes.first();
        while n != NIL {
            self.graph.nodes[n].data.beading = NIL;
            n = self.graph.nodes.next(n);
        }
        let mut e = self.graph.edges.first();
        while e != NIL {
            self.graph.edges[e].data.extrusion_junctions = NIL;
            e = self.graph.edges.next(e);
        }
    }

    /// From a quad, find the edge pointing to the node that is furthest away from the border of the polygon.
    fn get_quad_max_redge_to(&self, quad_start_edge: usize) -> usize {
        let g = &self.graph;
        let mut max_r: Coord = -1;
        let mut ret = NIL;
        let mut edge = quad_start_edge;
        while edge != NIL {
            let r = g.to_dtb(edge);
            if r > max_r {
                max_r = r;
                ret = edge;
            }
            edge = g.edges[edge].next;
        }
        if g.edges[ret].next == NIL && g.to_dtb(ret) - 5 < g.from_dtb(ret) {
            ret = g.edges[ret].prev;
        }
        ret
    }

    /// Propagate beading information from nodes that are closer to the edge (low radius R) to nodes that are farther from the edge (high R).
    fn propagate_beadings_upward(&mut self, upward_quad_mids: &[usize]) {
        for &upward_edge in upward_quad_mids.iter().rev() {
            let from = self.graph.edges[upward_edge].from;
            let to = self.graph.edges[upward_edge].to;
            if self.graph.nodes[to].data.bead_count >= 0 {
                // Don't override local beading
                continue;
            }
            if !self.has_beading(from) {
                // Only propagate if we have something to propagate
                continue;
            }
            let lower_beading = self.graph.nodes[from].data.beading;
            if self.has_beading(to) {
                // Only propagate to places where there is place
                continue;
            }
            let length = v_size(self.graph.nodes[to].p - self.graph.nodes[from].p);
            let mut upper_beading = self.beadings_store[lower_beading].clone();
            upper_beading.dist_to_bottom_source += length;
            upper_beading.is_upward_propagated_only = true;
            self.beadings_store.push(upper_beading);
            self.graph.nodes[to].data.beading = self.beadings_store.len() - 1;
        }
    }

    /// Propagate beading info from higher R nodes to lower R nodes.
    fn propagate_beadings_downward(&mut self, upward_quad_mids: &[usize]) {
        for &upward_quad_mid in upward_quad_mids {
            // Transfer beading information to lower nodes
            if !self.graph.is_central(upward_quad_mid) {
                // for equidistant edge: propagate from known beading to node with unknown beading
                let from = self.graph.edges[upward_quad_mid].from;
                let to = self.graph.edges[upward_quad_mid].to;
                if self.graph.nodes[from].data.distance_to_boundary == self.graph.nodes[to].data.distance_to_boundary
                    && self.has_beading(from)
                    && !self.has_beading(to)
                {
                    let twin = self.graph.edges[upward_quad_mid].twin;
                    self.propagate_beadings_downward_edge(twin);
                } else {
                    self.propagate_beadings_downward_edge(upward_quad_mid);
                }
            }
        }
    }

    fn propagate_beadings_downward_edge(&mut self, edge_to_peak: usize) {
        let from = self.graph.edges[edge_to_peak].from;
        let to = self.graph.edges[edge_to_peak].to;
        let length = v_size(self.graph.nodes[to].p - self.graph.nodes[from].p);
        let top = self.get_or_create_beading(to);
        if self.beadings_store[top].beading.total_thickness < self.graph.nodes[to].data.distance_to_boundary * 2 {
            crate::log_warn!("Top bead is beyond the center of the total width.");
        }

        if !self.has_beading(from) {
            // Set new beading if there is no beading associated with the node yet
            let mut propagated_beading = self.beadings_store[top].clone();
            propagated_beading.dist_from_top_source += length;
            if propagated_beading.beading.total_thickness < self.graph.nodes[from].data.distance_to_boundary * 2 {
                crate::log_warn!("Propagated bead is beyond the center of the total width.");
            }
            self.beadings_store.push(propagated_beading);
            self.graph.nodes[from].data.beading = self.beadings_store.len() - 1;
        } else {
            let bottom = self.graph.nodes[from].data.beading;
            let top_beading = self.beadings_store[top].clone();
            let bottom_dist_to_bottom_source = self.beadings_store[bottom].dist_to_bottom_source;
            let total_dist = top_beading.dist_from_top_source + length + bottom_dist_to_bottom_source;
            let denom = if self.beading_propagation_transition_dist < total_dist { self.beading_propagation_transition_dist } else { total_dist };
            let mut ratio_of_top = bottom_dist_to_bottom_source as f64 / denom as f64;
            ratio_of_top = if 0.0 < ratio_of_top { ratio_of_top } else { 0.0 };
            if ratio_of_top >= 1.0 {
                let mut b = top_beading;
                b.dist_from_top_source += length;
                self.beadings_store[bottom] = b;
            } else {
                let from_dtb = self.graph.nodes[from].data.distance_to_boundary;
                let merged_beading =
                    self.interpolate_switching(&top_beading.beading, ratio_of_top, &self.beadings_store[bottom].beading.clone(), from_dtb);
                if merged_beading.total_thickness < from_dtb * 2 {
                    crate::log_warn!("Merged bead is beyond the center of the total width.");
                }
                let mut b = BeadingPropagation::new(merged_beading);
                b.is_upward_propagated_only = false;
                self.beadings_store[bottom] = b;
            }
        }
    }

    /// Find a beading in between two other beadings.
    fn interpolate_switching(&self, left: &Beading, ratio_left_to_whole: f64, right: &Beading, switching_radius: Coord) -> Beading {
        let ret = self.interpolate(left, ratio_left_to_whole, right);

        // TODO: don't use toolpath locations past the middle!
        // TODO: stretch bead widths and locations of the higher bead count beading to fit in the left over space
        let mut next_inset_idx: Coord = left.toolpath_locations.len() as Coord - 1;
        while next_inset_idx >= 0 {
            if switching_radius > left.toolpath_locations[next_inset_idx as usize] {
                break;
            }
            next_inset_idx -= 1;
        }
        if next_inset_idx < 0 {
            // There is no next inset, because there is only one
            return ret;
        }
        if next_inset_idx + 1 == left.toolpath_locations.len() as Coord {
            // We cant adjust to fit the next edge because there is no previous one?!
            return ret;
        }
        let i = next_inset_idx as usize;
        if ret.toolpath_locations[i] > switching_radius {
            // One inset disappeared between left and the merged one
            // solve for ratio f:
            // f*l + (1-f)*r = s
            // f = (s-r) / (l-r)
            let mut new_ratio =
                (switching_radius - right.toolpath_locations[i]) as f64 / (left.toolpath_locations[i] - right.toolpath_locations[i]) as f64;
            let r = new_ratio + 0.1;
            new_ratio = if r < 1.0 { r } else { 1.0 };
            return self.interpolate(left, new_ratio, right);
        }
        ret
    }

    /// Creates a new Beading between two beadings, assuming that both have the same number of beads.
    fn interpolate(&self, left: &Beading, ratio_left_to_whole: f64, right: &Beading) -> Beading {
        let ratio_right_to_whole = 1.0 - ratio_left_to_whole;

        let mut ret = if left.total_thickness > right.total_thickness { left.clone() } else { right.clone() };
        let n = left.bead_widths.len().min(right.bead_widths.len());
        for inset_idx in 0..n {
            if left.bead_widths[inset_idx] == 0 || right.bead_widths[inset_idx] == 0 {
                ret.bead_widths[inset_idx] = 0; // 0-width wall markers stay 0-width.
            } else {
                ret.bead_widths[inset_idx] = (ratio_left_to_whole * left.bead_widths[inset_idx] as f64
                    + ratio_right_to_whole * right.bead_widths[inset_idx] as f64) as Coord;
            }
            ret.toolpath_locations[inset_idx] = (ratio_left_to_whole * left.toolpath_locations[inset_idx] as f64
                + ratio_right_to_whole * right.toolpath_locations[inset_idx] as f64) as Coord;
        }
        ret
    }

    /// Generate junctions for each bone.
    fn generate_junctions(&mut self) {
        let mut e = self.graph.edges.first();
        while e != NIL {
            self.generate_junctions_for_edge(e);
            e = self.graph.edges.next(e);
        }
    }

    fn generate_junctions_for_edge(&mut self, edge: usize) {
        let from = self.graph.edges[edge].from;
        let to = self.graph.edges[edge].to;
        if self.graph.nodes[from].data.distance_to_boundary > self.graph.nodes[to].data.distance_to_boundary {
            // Only consider the upward half-edges
            return;
        }

        let start_r = self.graph.nodes[to].data.distance_to_boundary; // higher R
        let end_r = self.graph.nodes[from].data.distance_to_boundary; // lower R

        let (from_bc, to_bc) = (self.graph.nodes[from].data.bead_count, self.graph.nodes[to].data.bead_count);
        if (from_bc == to_bc && from_bc >= 0) || end_r >= start_r {
            // No beads to generate
            return;
        }

        let beading_idx = self.get_or_create_beading(to);
        self.junctions_store.push(Vec::new());
        let j = self.junctions_store.len() - 1;
        self.graph.edges[edge].data.extrusion_junctions = j; // initialization

        let beading = &self.beadings_store[beading_idx].beading;
        if beading.total_thickness < self.graph.nodes[to].data.distance_to_boundary * 2 {
            crate::log_warn!("Generated junction is beyond the center of total width.");
        }

        let a = self.graph.nodes[to].p;
        let b = self.graph.nodes[from].p;
        let ab = b - a;

        let num_junctions = beading.toolpath_locations.len();
        // Compute starting junction_idx for this segment
        let mut junction_idx: usize = (num_junctions.max(1) - 1) / 2;
        while junction_idx < num_junctions {
            let bead_r = beading.toolpath_locations[junction_idx];
            // Adding a small epsilon (+1) to resolve an edge-case caused by rounding errors. (Would result in missing middle line.)
            if bead_r <= start_r + 1 {
                // Junction coinciding with start node is used in this function call
                break;
            }
            junction_idx = junction_idx.wrapping_sub(1);
        }

        // Robustness against odd segments which might lie just slightly outside of the range due to rounding errors
        // not sure if this is really needed (TODO)
        if junction_idx.wrapping_add(1) < num_junctions
            && beading.toolpath_locations[junction_idx.wrapping_add(1)] <= start_r + 5
            && beading.total_thickness < start_r + 5
        {
            junction_idx = junction_idx.wrapping_add(1);
        }

        let mut ret: LineJunctions = Vec::new();
        while junction_idx < num_junctions {
            // When junction_idx underflows, it'll be more than num_junctions too.
            let bead_r = beading.toolpath_locations[junction_idx];
            if bead_r < end_r {
                // Junction coinciding with a node is handled by the next segment
                break;
            }
            let mut junction = a + ab * (bead_r - start_r) / (end_r - start_r);
            if bead_r > start_r - 5 {
                // Snap to start node if it is really close, in order to be able to see 3-way intersection later on more robustly
                junction = a;
            }
            ret.push(ExtrusionJunction::new(junction, beading.bead_widths[junction_idx], junction_idx as Coord));
            junction_idx = junction_idx.wrapping_sub(1);
        }
        self.junctions_store[j] = ret;
    }

    /// Get the beading at a certain node of the skeletal graph, or create one if it doesn't have one yet.
    fn get_or_create_beading(&mut self, node: usize) -> usize {
        if !self.has_beading(node) {
            if self.graph.nodes[node].data.bead_count == -1 {
                // This bug is due to too small central edges
                const NEARBY_DIST: Coord = 100; // TODO
                let nearest_beading = self.get_nearest_beading(node, NEARBY_DIST);
                if nearest_beading != NIL {
                    return nearest_beading;
                }

                // Else make a new beading:
                let mut has_central_edge = false;
                let mut first = true;
                let mut dist = Coord::MAX;
                let g = &self.graph;
                let incident = g.nodes[node].incident_edge;
                let mut edge = incident;
                while edge != NIL && (first || edge != incident) {
                    if g.is_central(edge) {
                        has_central_edge = true;
                    }
                    let cand = g.to_dtb(edge) + v_size(g.to_p(edge) - g.from_p(edge));
                    dist = if cand < dist { cand } else { dist };
                    first = false;
                    edge = g.twin_next(edge);
                }
                if !has_central_edge {
                    crate::log_error!("Unknown beading for non-central node!");
                }
                self.graph.nodes[node].data.bead_count = self.beading_strategy.get_optimal_bead_count(dist * 2);
            }
            let data = &self.graph.nodes[node].data;
            let beading = self.beading_strategy.compute(data.distance_to_boundary * 2, data.bead_count);
            self.beadings_store.push(BeadingPropagation::new(beading));
            self.graph.nodes[node].data.beading = self.beadings_store.len() - 1;
        }
        self.graph.nodes[node].data.beading
    }

    /// In case we cannot find the beading of a node, get a beading from the nearest node.
    fn get_nearest_beading(&self, node: usize, max_dist: Coord) -> usize {
        let g = &self.graph;
        let mut further_edges = cppstd::PriorityQueue::new(|l: &(usize, Coord), r: &(usize, Coord)| l.1 > r.1);
        let mut first = true;
        let incident = g.nodes[node].incident_edge;
        let mut outgoing = incident;
        while outgoing != NIL && (first || outgoing != incident) {
            further_edges.push((outgoing, v_size(g.to_p(outgoing) - g.from_p(outgoing))));
            first = false;
            outgoing = g.twin_next(outgoing);
        }

        for _counter in 0..SKELETAL_TRAPEZOIDATION_BEAD_SEARCH_MAX {
            // Prevent endless recursion
            let here = match further_edges.pop() {
                None => return NIL,
                Some(h) => h,
            };
            if here.1 > max_dist {
                return NIL;
            }
            let here_to = g.edges[here.0].to;
            if self.has_beading(here_to) {
                return g.nodes[here_to].data.beading;
            } else {
                // recurse
                let twin = g.edges[here.0].twin;
                let mut further_edge = g.edges[here.0].next;
                while further_edge != NIL && further_edge != twin {
                    further_edges.push((further_edge, here.1 + v_size(g.to_p(further_edge) - g.from_p(further_edge))));
                    further_edge = g.twin_next(further_edge);
                }
            }
        }
        NIL
    }

    /// Add a new toolpath segment, defined between two extrusion-juntions.
    fn add_toolpath_segment(
        &mut self,
        from: &ExtrusionJunction,
        to: &ExtrusionJunction,
        is_odd: bool,
        mut force_new_path: bool,
        from_is_3way: bool,
        to_is_3way: bool,
    ) {
        if from == to {
            return;
        }

        let generated_toolpaths = &mut self.generated_toolpaths;

        let inset_idx = from.perimeter_index;
        if inset_idx >= generated_toolpaths.len() {
            generated_toolpaths.resize(inset_idx + 1, Vec::new());
        }
        let lines = &mut generated_toolpaths[inset_idx];
        if lines.is_empty()
            || lines.last().unwrap().is_odd != is_odd
            || lines.last().unwrap().junctions.last().unwrap().perimeter_index != inset_idx
        // inset_idx should always be consistent
        {
            force_new_path = true;
        }
        if !force_new_path
            && shorter_then(lines.last().unwrap().junctions.last().unwrap().p - from.p, 10)
            && (lines.last().unwrap().junctions.last().unwrap().w - from.w).abs() < 10
            && !from_is_3way
        // force new path at 3way intersection
        {
            lines.last_mut().unwrap().junctions.push(*to);
        } else if !force_new_path
            && shorter_then(lines.last().unwrap().junctions.last().unwrap().p - to.p, 10)
            && (lines.last().unwrap().junctions.last().unwrap().w - to.w).abs() < 10
            && !to_is_3way
        // force new path at 3way intersection
        {
            if !is_odd {
                crate::log_error!("Reversing even wall line causes it to be printed CCW instead of CW!");
            }
            lines.last_mut().unwrap().junctions.push(*from);
        } else {
            let mut line = ExtrusionLine::new(inset_idx, is_odd, false);
            line.junctions.push(*from);
            line.junctions.push(*to);
            lines.push(line);
        }
    }

    #[inline]
    fn junctions_of(&self, e: usize) -> &LineJunctions {
        let j = self.graph.edges[e].data.extrusion_junctions;
        assert!(j != NIL, "dereferencing missing extrusion junctions");
        &self.junctions_store[j]
    }

    /// Connect junctions in each quad.
    ///
    /// CuraEngine picks the next domain to process with `*unprocessed_quad_starts.begin()` on an
    /// `unordered_set<edge_t*>`, i.e. in an order that depends on heap addresses (and varies from
    /// run to run). This port (and the instrumented reference build) instead processes the domains
    /// in graph order, which is one of the orders CuraEngine itself can produce.
    fn connect_junctions(&mut self) {
        let mut unprocessed_quad_starts: HashSet<usize> = HashSet::new();
        let mut quad_start_order: Vec<usize> = Vec::new();
        let mut e = self.graph.edges.first();
        while e != NIL {
            if self.graph.edges[e].prev == NIL {
                unprocessed_quad_starts.insert(e);
                quad_start_order.push(e);
            }
            e = self.graph.edges.next(e);
        }

        let mut passed_odd_edges: HashSet<usize> = HashSet::new();
        let mut order_idx = 0usize;

        while !unprocessed_quad_starts.is_empty() {
            while !unprocessed_quad_starts.contains(&quad_start_order[order_idx]) {
                order_idx += 1;
            }
            let poly_domain_start = quad_start_order[order_idx];
            let mut quad_start = poly_domain_start;
            let mut new_domain_start = true;
            loop {
                let mut quad_end = quad_start;
                while self.graph.edges[quad_end].next != NIL {
                    quad_end = self.graph.edges[quad_end].next;
                }

                let edge_to_peak = self.get_quad_max_redge_to(quad_start);
                // walk down on both sides and connect junctions
                let edge_from_peak = self.graph.edges[edge_to_peak].next;

                unprocessed_quad_starts.remove(&quad_start);

                if !self.has_extrusion_junctions(edge_to_peak, false) {
                    self.junctions_store.push(Vec::new());
                    self.graph.edges[edge_to_peak].data.extrusion_junctions = self.junctions_store.len() - 1;
                }
                // The junctions on the edge(s) from the start of the quad to the node with highest R
                let mut from_junctions: LineJunctions = self.junctions_of(edge_to_peak).clone();
                let efp_twin = self.graph.edges[edge_from_peak].twin;
                if !self.has_extrusion_junctions(efp_twin, false) {
                    self.junctions_store.push(Vec::new());
                    self.graph.edges[efp_twin].data.extrusion_junctions = self.junctions_store.len() - 1;
                }
                // The junctions on the edge(s) from the end of the quad to the node with highest R
                let mut to_junctions: LineJunctions = self.junctions_of(efp_twin).clone();
                let etp_prev = self.graph.edges[edge_to_peak].prev;
                if etp_prev != NIL {
                    let from_prev_junctions = self.junctions_of(etp_prev).clone();
                    while !from_junctions.is_empty()
                        && !from_prev_junctions.is_empty()
                        && from_junctions.last().unwrap().perimeter_index <= from_prev_junctions[0].perimeter_index
                    {
                        from_junctions.pop();
                    }
                    from_junctions.extend_from_slice(&from_prev_junctions);
                    if self.graph.edges[etp_prev].prev != NIL {
                        crate::log_warn!("The edge we're about to connect is already connected.");
                    }
                }
                let efp_next = self.graph.edges[edge_from_peak].next;
                if efp_next != NIL {
                    let to_next_junctions = self.junctions_of(self.graph.edges[efp_next].twin).clone();
                    while !to_junctions.is_empty()
                        && !to_next_junctions.is_empty()
                        && to_junctions.last().unwrap().perimeter_index <= to_next_junctions[0].perimeter_index
                    {
                        to_junctions.pop();
                    }
                    to_junctions.extend_from_slice(&to_next_junctions);
                    if self.graph.edges[efp_next].next != NIL {
                        crate::log_warn!("The edge we're about to connect is already connected!");
                    }
                }
                if (from_junctions.len() as i64 - to_junctions.len() as i64).abs() > 1 {
                    crate::log_warn!(
                        "Can't create a transition when connecting two perimeters where the number of beads differs too much! {} vs. {}",
                        from_junctions.len(),
                        to_junctions.len()
                    );
                }

                let segment_count = from_junctions.len().min(to_junctions.len());
                for junction_rev_idx in 0..segment_count {
                    let from = from_junctions[from_junctions.len() - 1 - junction_rev_idx];
                    let to = to_junctions[to_junctions.len() - 1 - junction_rev_idx];
                    if from.perimeter_index != to.perimeter_index {
                        crate::log_warn!("Connecting two perimeters with different indices! Perimeter {} and {}", from.perimeter_index, to.perimeter_index);
                    }
                    let g = &self.graph;
                    let qs_to = g.edges[quad_start].to;
                    let qe_from = g.edges[quad_end].from;
                    let qs_to_data = &g.nodes[qs_to].data;
                    let qe_from_data = &g.nodes[qe_from].data;
                    let from_is_odd = qs_to_data.bead_count > 0
                        && qs_to_data.bead_count % 2 == 1 // quad contains single bead segment
                        && qs_to_data.transition_ratio == 0.0 // We're not in a transition
                        && junction_rev_idx == segment_count - 1 // Is single bead segment
                        && shorter_then(from.p - g.nodes[qs_to].p, 5);
                    let to_is_odd = qe_from_data.bead_count > 0
                        && qe_from_data.bead_count % 2 == 1 // quad contains single bead segment
                        && qe_from_data.transition_ratio == 0.0 // We're not in a transition
                        && junction_rev_idx == segment_count - 1 // Is single bead segment
                        && shorter_then(to.p - g.nodes[qe_from].p, 5);
                    let is_odd_segment = from_is_odd && to_is_odd;

                    let qs_next = g.edges[quad_start].next;
                    if is_odd_segment && passed_odd_edges.contains(&g.edges[qs_next].twin) {
                        // Only generate toolpath for odd segments once
                        continue; // Prevent duplication of single bead segments
                    }

                    let from_is_3way = from_is_odd && g.node_is_multi_intersection(qs_to);
                    let to_is_3way = to_is_odd && g.node_is_multi_intersection(qe_from);

                    passed_odd_edges.insert(qs_next);

                    self.add_toolpath_segment(&from, &to, is_odd_segment, new_domain_start, from_is_3way, to_is_3way);
                }
                new_domain_start = false;
                quad_start = self.graph.get_next_unconnected(quad_start);
                assert!(quad_start != NIL, "getNextUnconnected returned null");
                if quad_start == poly_domain_start {
                    break;
                }
            }
        }
    }

    /// Generate small segments for local maxima where the beading would only result in a single bead.
    fn generate_local_maxima_single_beads(&mut self) {
        let mut local_maxima_accumulator = Point2LL::new(0, 0);
        let mut width_accumulator: Coord = 0;
        let mut accumulator_count: usize = 0;

        let mut n = self.graph.nodes.first();
        while n != NIL {
            if self.has_beading(n) {
                let beading = &self.beadings_store[self.graph.nodes[n].data.beading].beading;
                if beading.bead_widths.len() % 2 == 1 && self.graph.node_is_local_maximum(n, true) {
                    let inset_index = beading.bead_widths.len() / 2;
                    let width = beading.bead_widths[inset_index];
                    let p = self.graph.nodes[n].p;
                    local_maxima_accumulator = local_maxima_accumulator + p;
                    width_accumulator += width;
                    accumulator_count += 1;
                    if !self.graph.node_is_central(n) {
                        Self::add_circle_to_toolpath(&mut self.generated_toolpaths, p, width, inset_index);
                    }
                }
            }
            n = self.graph.nodes.next(n);
        }

        if accumulator_count > 0 {
            let generated_toolpaths = &mut self.generated_toolpaths;
            let mut replace_with_local_maxima = generated_toolpaths.is_empty() || generated_toolpaths[0].is_empty();
            let mut total_path_length: Coord = 0;
            if !replace_with_local_maxima {
                let mut min_width = Coord::MAX;
                for line in &generated_toolpaths[0] {
                    total_path_length += line.length();
                    for j in &line.junctions {
                        min_width = min_width.min(j.w);
                    }
                }
                replace_with_local_maxima |= total_path_length <= min_width / 2;
            }
            if replace_with_local_maxima {
                let width = (width_accumulator as u64 / accumulator_count as u64) as Coord;
                local_maxima_accumulator = local_maxima_accumulator / accumulator_count as Coord;
                if generated_toolpaths.is_empty() {
                    generated_toolpaths.push(Vec::new());
                } else {
                    generated_toolpaths[0].clear();
                }
                Self::add_circle_to_toolpath(generated_toolpaths, local_maxima_accumulator, width, 0);
            }
        }
    }

    fn add_circle_to_toolpath(generated_toolpaths: &mut Vec<VariableWidthLines>, center: Point2LL, width: Coord, inset_index: usize) {
        if inset_index >= generated_toolpaths.len() {
            generated_toolpaths.resize(inset_index + 1, Vec::new());
        }
        const IS_ODD: bool = true;
        let mut line = ExtrusionLine::new(inset_index, IS_ODD, false);
        // total area to be extruded is pi*(w/2)^2 = pi*w*w/4
        // Width a constant extrusion width w, that would be a length of pi*w/4
        // If we make a small circle to fill up the hole, then that circle would have a circumference of 2*pi*r
        // So our circle needs to be such that r=w/8
        let r = width / 8;
        const N_SEGMENTS: usize = 6;
        let mut circle: Vec<ExtrusionJunction> = PolygonUtils::make_circle_points(center, r, N_SEGMENTS)
            .into_iter()
            .map(|p| ExtrusionJunction::new(p, width, inset_index as Coord))
            .collect();
        circle.push(circle[0]);
        line.junctions.extend(circle);
        generated_toolpaths[inset_index].push(line);
    }
}
